class Solution {
  public int lengthLongestPath(String input) {
    int[] lenAtDepth = new int[input.length() + 2]; // total path length up to each depth
    int best = 0;
    for (String line : input.split("\n")) {
      int depth = 0;
      while (depth < line.length() && line.charAt(depth) == '\t') depth++;
      String name = line.substring(depth);
      int len = (depth == 0 ? 0 : lenAtDepth[depth - 1] + 1) + name.length();
      lenAtDepth[depth] = len;
      if (name.contains(".")) best = Math.max(best, len);
    }
    return best;
  }
}
